#!/usr/bin/env python3
"""THE WORLD - one day of world news on a single page.

Draws a 1024x1024 newspaper front page and writes it as a PNG.
Pure Python 3 standard library only; the output is deterministic.

All text is rendered from a glyph atlas that is embedded below as
base64 data: ATLAS_B64 holds the zlib-compressed, 4-bit-quantised
atlas bitmap and GLYPHS_B64 holds the per-glyph metrics as JSON.
At run time the atlas is decoded, glyphs are blended into an RGB
framebuffer, and the framebuffer is written out as a PNG.
"""

import base64
import json
import os
import struct
import zlib

W = 1024
H = 1024

