# ------------------------------------------------------------------
# Page layout
# ------------------------------------------------------------------

M = 36
CW = 952


def draw_map(x, y, w, h):
    """Dotted world map with a red marker for each story."""
    fill_rect(x, y, w, h, MAPBG)
    cols = 112
    rows = 41
    cell_w = w / cols
    cell_h = h / rows
    radius = max(1, int(cell_w * 0.32))
    for row, first, last in MAP_RUNS:
        cy = int(y + (row + 0.5) * cell_h)
        for col in range(first, last + 1):
            cx = int(x + (col + 0.5) * cell_w)
            fill_circle(cx, cy, radius, MAPDOT)
    for lon, lat in MARKERS:
        mx = int(x + (lon + 180.0) / 360.0 * w)
        my = int(y + (80.0 - lat) / 136.0 * h)
        fill_circle(mx, my, 4, RED)
        fill_circle(mx, my, 2, CARD)


def build_page():
    # Paper background.
    fill_rect(0, 0, W, H, PAPER)

    # Masthead.
    fill_rect(0, 0, 1024, 96, NAVY)
    draw_text("mast", "THE WORLD", M, 58, CARD)
    draw_text("deck", "One day, one page - the stories that "
              "defined it", M, 84, PALE)
    draw_text_right("kick", DATELINE, M + CW, 34, CARD)
    draw_text_right("tiny", TAGLINE, M + CW, 56, PALE)
    fill_rect(0, 96, 1024, 5, RED)

    # Lead story, left column.
    ly = 116
    draw_text("kick", LEAD_KICKER.upper(), M, ly + 11, RED)
    head_end = draw_block("lead", LEAD_HEADLINE, M, ly + 52, 596,
                          3, 40, INK)
    deck_end = draw_block("deck", LEAD_DECK, M, head_end + 6, 596,
                          2, 18, DECKDARK)
    draw_block("body", LEAD_BODY, M, deck_end + 4, 596, 5, 15,
               BODYGREY)

    # Right rail: map and numbers.
    rx = 664
    rw = 324
    draw_text("kick", "THE DAY ON THE MAP", rx, ly + 11, NAVY)
    draw_map(rx, ly + 22, rw, 168)
    draw_text("tiny", MAP_CAPTION, rx, ly + 206, GREY)
    draw_text("kick", "BY THE NUMBERS", rx, ly + 226, NAVY)
    row_y = ly + 246
    for big, small in NUMBERS:
        draw_text("head2", big, rx, row_y + 10, RED)
        draw_block("tiny", small, rx + 86, row_y + 11, rw - 86, 2,
                   12, BODYGREY)
        row_y += 27

    # Story grid: 3 columns x 4 rows.
    gy = 470
    fill_rect(M, gy - 8, CW, 1, LINEC)
    colw = (CW - 40) // 3
    for i, (kicker, headline, body) in enumerate(STORIES):
        cx = M + (i % 3) * (colw + 20)
        cy = gy + (i // 3) * 104
        if i % 3 > 0:
            fill_rect(cx - 10, cy + 2, 1, 90, LINEC)
        draw_text("kick", kicker.upper(), cx, cy + 11, RED)
        head_end = draw_block("head2", headline, cx, cy + 35,
                              colw, 2, 19, INK)
        draw_block("body", body, cx, head_end + 1, colw, 2, 15,
                   BODYGREY)

    # Briefs band.
    by = gy + 4 * 104 + 8
    fill_rect(M, by, CW, 84, NAVY)
    draw_text("kick", "AROUND THE WORLD IN BRIEF", 50, by + 22,
              CARD)
    bw = (CW - 28 - 32) // 3
    for i, (place, text) in enumerate(BRIEFS):
        bx = 50 + (i % 3) * (bw + 16)
        iy = by + 44 + (i // 3) * 15
        label = place.upper() + " "
        draw_text("tiny", label, bx, iy, BRIEFORANGE)
        lw = text_width("tiny", label)
        draw_block("tiny", text, int(round(bx + lw)), iy,
                   int(bw - lw), 1, 13, BRIEFTEXT)

    # Footer.
    fy = by + 96
    draw_text("kick", "SPORT", M, fy + 12, RED)
    draw_text("head2", SPORT, 94, fy + 13, INK)
    draw_text_right("tiny", CREDITS, M + CW, fy + 12, GREY)


def main():
    build_page()
    write_png(output_path())


if __name__ == "__main__":
    main()
